class Solution {
public:
    bool primeSubOperation(vector<int>& nums) {
        const int V = 1000;
        // Sieve of Eratosthenes up to V.
        vector<bool> isPrime(V + 1, true);
        isPrime[0] = isPrime[1] = false;
        for (int i = 2; i * i <= V; ++i) {
            if (isPrime[i]) {
                for (int j = i * i; j <= V; j += i) isPrime[j] = false;
            }
        }
        // largestPrimeBelow[v] = greatest prime strictly less than v.
        vector<int> largestPrimeBelow(V + 2, 0);
        int last = 0;
        for (int v = 0; v <= V + 1; ++v) {
            largestPrimeBelow[v] = last;
            if (v >= 2 && v <= V && isPrime[v]) last = v;
        }

        int prev = 0;
        for (int x : nums) {
            int target = x - prev;
            int p = 0;
            if (target >= 0 && target <= V + 1) p = largestPrimeBelow[target];
            if (p > 0) {
                prev = x - p;            // subtract largest valid prime
            } else if (x > prev) {
                prev = x;                // leave unchanged
            } else {
                return false;
            }
        }
        return true;
    }
};
